class Solution {
    public int countGoodRectangles(int[][] rectangles){
        int maximum=0,answer=0;
        for(int[] rectangle:rectangles){
            int side=Math.min(rectangle[0],rectangle[1]);
            if(side>maximum){
                maximum=side;
                answer=1;
            }else if(side==maximum)answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countGoodRectangles(rectangles:Array<IntArray>):Int{
        val sides=rectangles.map{
            minOf(it[0],it[1])
        };
        val maximum=sides.maxOrNull()!!;
        return sides.count{
            it==maximum
        }
    }
}

